glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec2 foilPosition;
out vec4 tint;
vec4 vert () {
  vec4 position = vec4(a_position, 1.0);
  position = cc_matWorld * position;
  uv = a_texCoord;
  foilPosition = a_position.xy;
  tint = a_color;
  return cc_matViewProj * position;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
uniform sampler2D mainTexture;
layout(std140) uniform InkParameters {
  vec4 pull;
  vec4 filmLight;
  vec4 tearTip;
  vec4 mouth0;
  vec4 mouth1;
  vec4 mouth2;
};
in vec2 uv;
in vec2 foilPosition;
in vec4 tint;
float bell(float offset, float width) {
  float x = offset / width;
  return exp(-x*x);
}
float bentFold(float offset, float width) {
  float x = offset / width;
  return x * exp(-x*x);
}
float luminance(vec3 rgb) {
  return dot(rgb, vec3(.299,.587,.114));
}
float reflectedFlux(vec4 mouth) {
  vec2 d = foilPosition-mouth.xy;
  float standOff = 13.;
  float across = d.y*d.y + standOff*standOff;
  float r = .5*max(mouth.z, 1.);
  vec2 ends = d.x+vec2(r,-r);
  vec2 cosine = ends*inversesqrt(across+ends*ends);
  return (cosine.x-cosine.y)*mouth.w*standOff/(2.*r*across);
}
vec4 frag () {
  vec4 print = texture(mainTexture, uv);
  if (print.a < .001) return vec4(0.);
  float luma = luminance(print.rgb);
  float neighbour = luminance(texture(mainTexture,
      clamp(uv + vec2(.0031,-.0010), 0., 1.)).rgb);
  float slope = clamp((neighbour - luma) * .85, -.19, .19);
  float fromCut = uv.y - tearTip.y;
  float z = max(0., fromCut);
  float fromTip = (uv.x - tearTip.x)*tearTip.z;
  float tension = pull.y * exp(-7.*z - 15.*max(0.,-fromCut)) * bell(fromTip, .30);
  float wrinkle = bentFold(fromTip + z*(.86 + .22*pull.z), .047)
                - .68*bentFold(fromTip - z*(.97 + .21*pull.z), .031);
  float edge = .14*bentFold(uv.x - .055 - .017*sin(uv.y*7.5), .036)
             - .17*bentFold(uv.x - .94 + .023*sin(uv.y*7.), .041);
  float crimp = 1. - smoothstep(filmLight.w*.60, filmLight.w*1.12, min(uv.y, 1.-uv.y));
  float idle = .027*sin(cc_time.x*.57)*filmLight.z*(1.-pull.y);
  float normal = (uv.x-.5)*1.55 + (uv.y-.48)*.29 + slope*(.56+.84*crimp)
               + edge + wrinkle*tension*.82;
  float source = -.34 + idle + .47*filmLight.x + .19*filmLight.y
               + (.23 + .33*pull.x)*pull.y + .16*pull.w;
  #if RIBBON_SURFACE
    normal += tearTip.z*tint.r*.15;
  #endif
  float angle = normal - source;
  float panel = bell(angle,.24);
  float bevel = bell(angle + .115,.074);
  float bounce = bell(normal + .31*source - .66,.19);
  float silver = smoothstep(.16,.78,luma);
  float gold = smoothstep(.035,.23,print.r-print.b) * smoothstep(.22,.59,print.g);
  float metal = max(silver*.78, gold);
  vec3 lamp = mix(vec3(.84,.90,.93), vec3(.99,.87,.67),gold);
  float deposit = .034 + .19*metal + .044*crimp;
  float specular = (panel*.69 + bevel*.36) * deposit;
  float fill = bounce * (.014 + .035*metal + .017*crimp);
  vec3 colour = print.rgb * (1. + .042*edge + .27*wrinkle*tension);
  colour += (1.-colour) * (lamp*specular + vec3(.74,.85,.89)*fill);
  if (mouth0.w > .001) {
    float irradiance = reflectedFlux(mouth0)+reflectedFlux(mouth1)+reflectedFlux(mouth2);
    float indirect = irradiance/(1.+irradiance);
    #if RIBBON_SURFACE
      float facingIn = .52*tint.g + .10*tint.r*tint.r;
    #else
      float facingIn = smoothstep(.018,.30,1.-tint.r);
    #endif
    float relief = smoothstep(.012,.13,abs(slope));
    vec3 reflected = mix(vec3(.245,.26,.28),vec3(.46,.255,.082),tearTip.w);
    vec3 returnLight = reflected*(.07+.22*metal+.33*relief);
    colour += (1.-colour)*returnLight*facingIn*indirect;
  }
  #if RIBBON_SURFACE
    float glint = clamp(.31+.55*panel+.27*bevel,0.,1.);
    vec3 rawEdge = mix(vec3(.29,.29,.31),vec3(.74,.72,.68),glint);
    return vec4(mix(colour,rawEdge,tint.g*.54),print.a*tint.a);
  #else
    return vec4(colour,print.a)*tint;
  #endif
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

